package com.madhukar.upisplitter.controller;
import com.madhukar.upisplitter.dto.ApiDtos;import com.madhukar.upisplitter.dto.ApiResponseFactory;import com.madhukar.upisplitter.service.S3StorageService;import org.springframework.http.MediaType;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/aws") public class AwsController {private final S3StorageService s3;public AwsController(S3StorageService s){this.s3=s;}@PostMapping(value="/receipt",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ApiDtos.ApiResponse<String> upload(@RequestParam MultipartFile file)throws Exception{if(file.isEmpty())throw new IllegalArgumentException("File is empty");if(file.getSize()>5_000_000)throw new IllegalArgumentException("File must be 5 MB or smaller");String key=s3.upload(file);return ApiResponseFactory.ok("Receipt uploaded to S3",key);}}
